package com.savewhy.app;
import android.graphics.*;
import java.io.*;
import java.nio.file.Files;
import java.util.*;
import java.util.zip.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class MediaBackupTest {
    File directory;ImageStore images;
    @Before public void setup()throws Exception{directory=Files.createTempDirectory("savewhy-media-test").toFile();images=new ImageStore(new File(directory,"images"));}
    @After public void cleanup(){remove(directory);}
    private void remove(File f){if(f==null)return;File[] files=f.listFiles();if(files!=null)for(File child:files)remove(child);f.delete();}
    private byte[] png()throws Exception{Bitmap b=Bitmap.createBitmap(1080,2400,Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);ByteArrayOutputStream out=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.PNG,100,out);b.recycle();return out.toByteArray();}
    private Card card(String image){return new Card("image","","Screenshot","Al","Later",1,false,Collections.emptyList(),"",image,Collections.singletonList("Shopping"),"headphones","ready");}
    private byte[] zip(Map<String,byte[]> entries)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(out)){for(Map.Entry<String,byte[]> e:entries.entrySet()){z.putNextEntry(new ZipEntry(e.getKey()));z.write(e.getValue());z.closeEntry();}}return out.toByteArray();}
    @Test public void galleryCopySurvivesOriginalDeletionAndKeepsReadableResolution()throws Exception{File original=new File(directory,"original.png");Files.write(original.toPath(),png());String id=images.ingest(new FileInputStream(original));original.delete();assertTrue(images.exists(id));Bitmap b=images.bitmap(id,2560);assertEquals(1080,b.getWidth());assertEquals(2400,b.getHeight());b.recycle();assertEquals(id,ImageStore.digest(Files.readAllBytes(images.file(id).toPath())));}
    @Test public void completeZipRestoresImageTagsAndOcrToAnotherInstallation()throws Exception{String id=images.ingest(new ByteArrayInputStream(png()));Card card=card(id);ByteArrayOutputStream out=new ByteArrayOutputStream();MediaBackup.write(out,CardCodec.encode(Collections.singletonList(card)),Collections.singletonList(card),images,new File(directory,"previews"));ImageStore restored=new ImageStore(new File(directory,"restored"));try(MediaBackup.Pending pending=MediaBackup.read(new ByteArrayInputStream(out.toByteArray()),directory,restored);MediaBackup.Install install=pending.install(restored,new File(directory,"restored-previews"),pending.cards)){assertTrue(restored.exists(id));assertEquals(card.tags,pending.cards.get(0).tags);assertEquals("headphones",pending.cards.get(0).recognizedText);install.commit();}assertTrue(restored.exists(id));}
    @Test public void canceledInstallRollsBackNewAssets()throws Exception{String id=images.ingest(new ByteArrayInputStream(png()));Card c=card(id);ByteArrayOutputStream out=new ByteArrayOutputStream();MediaBackup.write(out,CardCodec.encode(Collections.singletonList(c)),Collections.singletonList(c),images,new File(directory,"previews"));ImageStore restored=new ImageStore(new File(directory,"restored"));try(MediaBackup.Pending pending=MediaBackup.read(new ByteArrayInputStream(out.toByteArray()),directory,restored);MediaBackup.Install install=pending.install(restored,new File(directory,"restored-previews"),pending.cards)){assertTrue(restored.exists(id));}assertFalse(restored.exists(id));}
    @Test public void unsafePathsMissingImagesAndWrongChecksumsFailBeforeInstall()throws Exception{String id=images.ingest(new ByteArrayInputStream(png()));String json=CardCodec.encode(Collections.singletonList(card(id)));assertThrows(IOException.class,()->MediaBackup.read(new ByteArrayInputStream(zip(Collections.singletonMap("../cards.json",json.getBytes("UTF-8")))),directory,images));assertThrows(IOException.class,()->MediaBackup.read(new ByteArrayInputStream(zip(Collections.singletonMap("records.json",json.getBytes("UTF-8")))),directory,images));Map<String,byte[]> bad=new LinkedHashMap<>();bad.put("records.json",json.getBytes("UTF-8"));bad.put("images/"+id+".jpg",new byte[]{1,2,3});assertThrows(IOException.class,()->MediaBackup.read(new ByteArrayInputStream(zip(bad)),directory,images));}
    @Test public void oversizedEntryAndUnreferencedImageAreRejected()throws Exception{String json=CardCodec.encode(Collections.emptyList());Map<String,byte[]> bad=new LinkedHashMap<>();bad.put("records.json",json.getBytes("UTF-8"));bad.put("images/"+String.join("",Collections.nCopies(64,"a"))+".jpg",new byte[ImageStore.MAX_IMAGE_BYTES+1]);assertThrows(IOException.class,()->MediaBackup.read(new ByteArrayInputStream(zip(bad)),directory,images));String id=images.ingest(new ByteArrayInputStream(png()));bad.clear();bad.put("records.json",json.getBytes("UTF-8"));bad.put("images/"+id+".jpg",Files.readAllBytes(images.file(id).toPath()));assertThrows(IOException.class,()->MediaBackup.read(new ByteArrayInputStream(zip(bad)),directory,images));}
    @Test public void oldJsonImportRemainsSupportedButIncompleteImageJsonIsRejected()throws Exception{Card link=new Card("link","https://example.com","Link","Al","Later",0,false,Collections.emptyList());try(MediaBackup.Pending pending=MediaBackup.read(new ByteArrayInputStream(CardCodec.encode(Collections.singletonList(link)).getBytes("UTF-8")),directory,images)){assertEquals(1,pending.cards.size());assertFalse(pending.cards.get(0).isImage());}String id=images.ingest(new ByteArrayInputStream(png()));assertThrows(IOException.class,()->MediaBackup.read(new ByteArrayInputStream(CardCodec.encode(Collections.singletonList(card(id))).getBytes("UTF-8")),directory,images));}
    @Test public void savedImagesShareTheSameTwentyRecordLimitAsLinks()throws Exception{CardStore store=new CardStore(new File(directory,"records"),()->false);store.load();for(int i=0;i<19;i++)store.save(new Card("link"+i,"https://example.com/"+i,"Link","Al","Later",0,false,Collections.emptyList()));String id=images.ingest(new ByteArrayInputStream(png()));store.save(card(id));assertEquals(20,store.all().size());assertThrows(CardStore.LimitException.class,()->store.save(new Card("extra","https://example.com/extra","Link","Al","Later",0,false,Collections.emptyList())));}
    @Test public void cleanupPreservesReferencedImagesAndUndoGracePeriod()throws Exception{String id=images.ingest(new ByteArrayInputStream(png()));File file=images.file(id);long now=System.currentTimeMillis();file.setLastModified(now-8L*86400000);images.cleanup(Collections.singleton(id),now);assertTrue(file.exists());images.retainForUndo(id);images.cleanup(Collections.emptySet(),now);assertTrue(file.exists());file.setLastModified(now-8L*86400000);images.cleanup(Collections.emptySet(),now);assertFalse(file.exists());}
    @Test public void corruptImageAndOversizedInputCannotCreateAssets(){assertThrows(Exception.class,()->images.ingest(new ByteArrayInputStream(new byte[]{1,2,3})));assertThrows(IOException.class,()->images.ingest(new ByteArrayInputStream(new byte[ImageStore.MAX_INPUT_BYTES+1])));}
}
